//! Bounded thread-safe LRU cache with TTL.
//!
//! Public API:
//! - `LruCache<K, V>`: The cache type.
//! - `LruCache::new(capacity: usize, clock: Arc<dyn Clock>)`: Create a new cache with given capacity and clock.
//! - `LruCache::get(&self, key: &K) -> Option<V>`: Get a value if present and not expired.
//! - `LruCache::insert(&self, key: K, value: V, ttl: Duration)`: Insert or update a key-value pair with TTL.
//! - `LruCache::remove(&self, key: &K) -> Option<V>`: Remove a key and return its value if present.
//! - `LruCache::len(&self) -> usize`: Return the number of non-expired entries.
//! - `Clock` trait: Injectable clock for deterministic tests.
//! - `SystemClock`: Default clock using std::time::Instant.
//! - `MockClock`: Deterministic clock for tests.
//!
//! Concurrency: All public methods acquire a Mutex lock. The cache is shared via Arc.
//! LRU order is maintained via a linked list (Vec-based for simplicity without unsafe).
//! TTL is checked on access; expired entries are lazily removed.

use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

/// Trait for injectable clock.
pub trait Clock: Send + Sync {
    fn now(&self) -> Instant;
}

/// System clock using std::time::Instant.
pub struct SystemClock;

impl Clock for SystemClock {
    fn now(&self) -> Instant {
        Instant::now()
    }
}

/// Mock clock for deterministic tests.
pub struct MockClock {
    inner: Mutex<Instant>,
}

impl MockClock {
    pub fn new(start: Instant) -> Self {
        MockClock {
            inner: Mutex::new(start),
        }
    }

    pub fn advance(&self, duration: Duration) {
        let mut guard = self.inner.lock().unwrap();
        *guard += duration;
    }
}

impl Clock for MockClock {
    fn now(&self) -> Instant {
        let guard = self.inner.lock().unwrap();
        *guard
    }
}

/// Internal entry in the cache.
struct Entry<V> {
    value: V,
    expires_at: Instant,
    /// Index in the LRU list (position in the linked list).
    lru_index: usize,
}

/// LRU list node: stores key and next/prev indices.
struct LruNode<K> {
    key: K,
    next: Option<usize>,
    prev: Option<usize>,
}

/// The LRU cache.
pub struct LruCache<K, V>
where
    K: Clone + Eq + std::hash::Hash + Send + 'static,
    V: Clone + Send + 'static,
{
    capacity: usize,
    clock: Arc<dyn Clock>,
    inner: Mutex<CacheInner<K, V>>,
}

struct CacheInner<K, V>
where
    K: Clone + Eq + std::hash::Hash,
    V: Clone,
{
    map: HashMap<K, Entry<V>>,
    lru_nodes: Vec<LruNode<K>>,
    /// Index of the most recently used node.
    head: Option<usize>,
    /// Index of the least recently used node.
    tail: Option<usize>,
    /// Free list for reusing LruNode slots.
    free_list: Vec<usize>,
}

impl<K, V> LruCache<K, V>
where
    K: Clone + Eq + std::hash::Hash + Send + 'static,
    V: Clone + Send + 'static,
{
    /// Create a new LRU cache with the given capacity and clock.
    /// If capacity is 0, the cache will not store any entries.
    pub fn new(capacity: usize, clock: Arc<dyn Clock>) -> Self {
        LruCache {
            capacity,
            clock,
            inner: Mutex::new(CacheInner {
                map: HashMap::new(),
                lru_nodes: Vec::new(),
                head: None,
                tail: None,
                free_list: Vec::new(),
            }),
        }
    }

    /// Get a value if present and not expired.
    /// Returns None if the key is not present or has expired.
    pub fn get(&self, key: &K) -> Option<V> {
        let now = self.clock.now();
        let mut inner = self.inner.lock().unwrap();
        inner.get_internal(key, now)
    }

    /// Insert or update a key-value pair with TTL.
    /// If the cache is at capacity, the least recently used entry is evicted.
    /// If capacity is 0, the insert is a no-op.
    pub fn insert(&self, key: K, value: V, ttl: Duration) {
        if self.capacity == 0 {
            return;
        }
        let now = self.clock.now();
        let expires_at = now + ttl;
        let mut inner = self.inner.lock().unwrap();
        inner.insert_internal(key, value, expires_at, now);
    }

    /// Remove a key and return its value if present.
    pub fn remove(&self, key: &K) -> Option<V> {
        let mut inner = self.inner.lock().unwrap();
        inner.remove_internal(key)
    }

    /// Return the number of non-expired entries.
    pub fn len(&self) -> usize {
        let now = self.clock.now();
        let mut inner = self.inner.lock().unwrap();
        inner.len_internal(now)
    }

    /// Check if the cache is empty (no non-expired entries).
    pub fn is_empty(&self) -> bool {
        self.len() == 0
