// Task represents a unit of work to be executed by the worker pool.
// The function should respect the provided context for cancellation.
type Task func(ctx context.Context) (interface{}, error)

// Result holds the outcome of a task execution.
type Result struct {
	Value interface{}
	Err   error
}

// Pool is a bounded worker pool with context cancellation, backpressure,
// panic recovery, graceful shutdown, and deterministic result delivery.
//
// Public API:
//   - NewPool(capacity int) *Pool: Creates a new pool with the given worker capacity.
//     Capacity must be positive. Zero or negative capacity returns an error.
//   - Submit(ctx context.Context, task Task) (<-chan Result, error): Submits a task
//     to the pool. Returns a channel that will receive exactly one Result.
//     If the pool is full, it blocks until a worker is available or ctx is canceled.
//     If the pool is closed, returns ErrPoolClosed.
//     If ctx is canceled while waiting for a slot, returns ErrContextCanceled.
//   - Shutdown(ctx context.Context) error: Gracefully shuts down the pool.
//     Stops accepting new tasks, waits for in-flight tasks to complete or ctx to cancel.
//     Returns ErrContextCanceled if ctx is canceled before all tasks finish.
//   - Close(): Immediately closes the pool, rejecting new submissions.
//     In-flight tasks continue to run but their results may be discarded.
//
// Concurrency invariants:
//   - At most `capacity` tasks execute concurrently.
//   - Each submitted task produces exactly one Result on its result channel.
//   - Panics in tasks are recovered and converted to errors in Result.
//   - No goroutine leaks: all worker goroutines exit after Shutdown/Close.
//   - No data races: all shared state is protected by mutexes or atomic operations.
type Pool struct {
	capacity   int
	tasks      chan taskEnvelope
	workers    sync.WaitGroup
	closed     atomic.Bool
	shutdownCh chan struct{}
	closeOnce  sync.Once
}

// taskEnvelope wraps a task with its result channel and context.
type taskEnvelope struct {
	ctx    context.Context
	task   Task
	result chan Result
}

// ErrPoolClosed is returned when submitting to a closed pool.
var ErrPoolClosed = errors.New("worker pool is closed")

// ErrContextCanceled is returned when context is canceled during submission or shutdown.
var ErrContextCanceled = errors.New("context canceled")

// ErrInvalidCapacity is returned when creating a pool with non-positive capacity.
var ErrInvalidCapacity = errors.New("capacity must be positive")

// NewPool creates a new worker pool with the given capacity.
// Capacity must be a positive integer. Returns an error if capacity <= 0.
func NewPool(capacity int) (*Pool, error) {
	if capacity <= 0 {
		return nil, ErrInvalidCapacity
	}
	p := &Pool{
		capacity:   capacity,
		tasks:      make(chan taskEnvelope, capacity),
		shutdownCh: make(chan struct{}),
	}
	// Start worker goroutines
	for i := 0; i < capacity; i++ {
		p.workers.Add(1)
		go p.worker()
	}
	return p, nil
}

// worker is the main loop for each worker goroutine.
// It reads tasks from the tasks channel and executes them.
// Exits when the pool is closed or shutdown is initiated.
func (p *Pool) worker() {
	defer p.workers.Done()
	for {
		select {
		case <-p.shutdownCh:
			// Drain remaining tasks? No, we want graceful shutdown to wait for in-flight.
			// But if shutdown is called, we should stop accepting new tasks.
			// Workers exit after current task completes.
			return
		case envelope, ok := <-p.tasks:
			if !ok {
				// Channel closed, exit
				return
			}
			p.executeTask(envelope)
		}
	}
}

