//! Bounded thread-safe LRU cache with TTL.
//!
//! Public API:
//! - `Cache<K, V>`: a generic cache keyed by `K` (must be `Eq + Hash + Clone`) storing values `V` (must be `Clone`).
//! - `Cache::new(capacity: usize, ttl: Duration, clock: Arc<dyn Clock>) -> Self`
//! - `Cache::get(&self, key: &K) -> Option<V>`
//! - `Cache::insert(&self, key: K, value: V)`
//! - `Cache::remove(&self, key: &K) -> Option<V>`
//! - `Cache::len(&self) -> usize`
//! - `Clock` trait with `now() -> Instant` for deterministic testing.
//! - `SystemClock` implements `Clock` using `std::time::Instant`.
//! - `TestClock` implements `Clock` with manual time advancement for tests.
//!
//! Concurrency: All public methods acquire a single `Mutex` guarding the internal state.
//! Ownership: The cache is wrapped in `Arc` for shared access across threads. The internal
//! state is protected by `Mutex`. Keys and values are cloned on get/insert to satisfy
//! `Clone` bounds and allow safe sharing.
//!
//! Edge cases handled:
//! - Zero capacity: insert is a no-op, get/remove return None, len is 0.
//! - Negative capacity: not possible in Rust (usize), but zero is handled.
//! - TTL expiry: entries are lazily expired on access; expired entries are removed on get.
//! - Eviction: when capacity is reached, the least recently used entry is evicted.
//! - Concurrent access: all operations are serialized via Mutex.
//! - Deterministic clock: TestClock allows precise control over time for testing expiry.

use std::collections::HashMap;
use std::hash::Hash;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

/// Trait for providing the current time, enabling deterministic testing.
pub trait Clock: Send + Sync {
    /// Returns the current instant.
    fn now(&self) -> Instant;
}

/// A clock that uses the system's monotonic clock.
pub struct SystemClock;

impl Clock for SystemClock {
    fn now(&self) -> Instant {
        Instant::now()
    }
}

/// A test clock that allows manual advancement of time.
pub struct TestClock {
    inner: Mutex<Instant>,
}

impl TestClock {
    /// Creates a new TestClock starting at the given instant.
    pub fn new(start: Instant) -> Self {
        TestClock {
            inner: Mutex::new(start),
        }
    }

    /// Advances the clock by the given duration.
    pub fn advance(&self, duration: Duration) {
        let mut guard = self.inner.lock().unwrap();
        *guard += duration;
    }
