// Package workerpool provides a bounded worker pool with context cancellation,
// task submission with backpressure, panic recovery, graceful shutdown, and
// deterministic result delivery.
//
// Public API:
//
//   - NewPool(capacity int, workers int) *Pool
//     Creates a new pool with the given queue capacity and number of workers.
//     capacity must be >= 0. workers must be >= 1.
//
//   - (*Pool).Submit(ctx context.Context, task func() (interface{}, error)) error
//     Submits a task to the pool. Returns an error if the pool is closed or
//     if the context is canceled before the task can be enqueued.
//     If the queue is full, Submit blocks until space is available or ctx is canceled.
//
//   - (*Pool).Shutdown()
//     Initiates graceful shutdown. No new tasks are accepted. Existing tasks
//     in the queue and currently running tasks are allowed to complete.
//     Shutdown is idempotent.
//
//   - (*Pool).Wait()
//     Blocks until all workers have finished processing all queued tasks and
//     all workers have exited. Must be called after Shutdown.
//
//   - (*Pool).Result() <-chan Result
//     Returns a channel that receives results from completed tasks.
//     The channel is closed when all workers have exited and all results have
//     been delivered.
//
//   - Result struct
//     Contains the task's return value, error, and any panic information.
//
// Concurrency invariants:
//   - The number of concurrently running tasks never exceeds the number of workers.
//   - The number of queued tasks never exceeds the capacity.
//   - All tasks submitted before Shutdown are eventually processed or canceled.
//   - No goroutine leaks: all worker goroutines exit after Shutdown and Wait.
//   - No data races: all shared state is protected by mutexes or channels.
//   - Panics in tasks are recovered and reported in Result.
//   - Results are delivered in a deterministic order (FIFO by submission order).
package workerpool

import (
	"context"
	"errors"
	"fmt"
	"sync"
)

// Result represents the outcome of a task execution.
type Result struct {
	// Value is the value returned by the task function, if any.
	Value interface{}
	// Err is the error returned by the task function, if any.
	Err error
	// Panic is the panic value recovered from the task, if any.
	Panic interface{}
	// TaskID is a unique identifier for the task, useful for correlation.
	TaskID string
}

// Pool is a bounded worker pool.
type Pool struct {
	capacity int
	workers  int

	// queue holds pending tasks. It is a buffered channel of task wrappers.
	queue chan *taskWrapper

	// resultChan delivers results to consumers.
	resultChan chan Result

	// wg tracks active worker goroutines.
	wg sync.WaitGroup

	// closeOnce ensures Shutdown is idempotent.
	closeOnce sync.Once

	// closed indicates whether the pool has been shut down.
	closed bool
	closedMu sync.Mutex

	// taskCounter provides unique task IDs.
	taskCounter uint64
	taskCounterMu sync.Mutex
}

// taskWrapper holds a task and its metadata.
type taskWrapper struct {
	task   func() (interface{}, error)
	taskID string
}

// NewPool creates a new worker pool.
// capacity is the maximum number of tasks that can be queued.
// workers is the number of worker goroutines.
// capacity must be >= 0, workers must be >= 1.
func NewPool(capacity int, workers int) *Pool {
	if capacity < 0 {
		panic("capacity must be >= 0")
	}
	if workers < 1 {
		panic("workers must be >= 1")
	}

	p := &Pool{
		capacity:   capacity,
		workers:    workers,
		queue:      make(chan *taskWrapper, capacity),
		resultChan: make(chan Result, capacity+workers), // buffer to avoid blocking workers
	}

	// Start workers.
	for i := 0; i < workers; i++ {
		p.wg.Add(1)
		go p.worker()
	}

	return p
}

// Submit submits a task to the pool.
// If the pool is closed, it returns an error.
// If the context is canceled before the task can be enqueued, it returns the context error.
// If the queue is full, Submit blocks until space is available or ctx is canceled.
func (p *Pool) Submit(ctx context.Context, task func() (interface{}, error)) error {
	if task == nil {
		return errors.New("task must not be nil")
	}

	p.closedMu.Lock()
	if p.closed {
		p.closedMu.Unlock()
		return errors.New("pool is closed")
	}
	p.closedMu.Unlock()

	// Generate a unique task ID.
	p.taskCounterMu.Lock()
	p.taskCounter++
	taskID := fmt.Sprintf("task_%d", p.taskCounter)
	p.taskCounterMu.Unlock()

	tw := &taskWrapper{
		task:   task,
		taskID: taskID,
	}

	// Try to enqueue the task, respecting context cancellation.
	select {
	case p.queue <- tw:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
