//! Bounded thread-safe LRU cache with TTL.
//!
//! Public API:
//! - `LruCache<K, V>`: The cache type.
//! - `LruCache::new(capacity: usize, clock: Arc<dyn Clock>)`: Create a new cache with given capacity and clock.
//! - `LruCache::get(&self, key: &K) -> Option<V>`: Get a value if present and not expired.
//! - `LruCache::insert(&self, key: K, value: V, ttl: Duration)`: Insert or update a key-value pair with TTL.
//! - `LruCache::remove(&self, key: &K) -> Option<V>`: Remove a key and return its value if present.
//! - `LruCache::len(&self) -> usize`: Return the number of non-expired entries.
//! - `Clock`: Trait for injectable clock.
//! - `SystemClock`: Default clock using std::time::Instant.
//! - `MockClock`: Deterministic clock for tests.
//!
//! Concurrency: All operations are thread-safe via Arc<Mutex<...>>.
//! Ownership: Keys and values are owned by the cache. Cloning is required for get.
//! Edge cases: Zero capacity means no entries can be stored. Negative capacity is not possible (usize).
//! Eviction: When capacity is reached, the least recently used entry is evicted.
//! TTL: Entries expire after their TTL from insertion time. Expired entries are treated as absent.
//! Deterministic clock: MockClock allows tests to control time.

use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

/// Trait for a clock that can be injected for testing.
pub trait Clock: Send + Sync {
    /// Returns the current time as an Instant.
    fn now(&self) -> Instant;
}

/// Default clock using std::time::Instant.
pub struct SystemClock;

impl Clock for SystemClock {
    fn now(&self) -> Instant {
        Instant::now()
    }
}

/// Mock clock for deterministic testing.
pub struct MockClock {
    inner: Mutex<Instant>,
}

impl MockClock {
    /// Create a new MockClock starting at the given instant.
    pub fn new(start: Instant) -> Self {
        MockClock {
            inner: Mutex::new(start),
        }
    }

    /// Advance the clock by the given duration.
    pub fn advance(&self, duration: Duration) {
        let mut guard = self.inner.lock().unwrap();
        *guard += duration;
    }
}

impl Clock for MockClock {
    fn now(&self) -> Instant {
        let guard = self.inner.lock().unwrap();
        *guard
    }
}

/// Internal entry stored in the cache.
struct Entry<V> {
    value: V,
    expires_at: Instant,
}

/// Internal LRU list node.
struct LruNode<K> {
    key: K,
    prev: Option<usize>,
    next: Option<usize>,
}

/// Internal LRU list using indices into a Vec.
struct LruList<K> {
    nodes: Vec<LruNode<K>>,
    head: Option<usize>, // most recently used
    tail: Option<usize>, // least recently used
    free_list: Vec<usize>,
}

impl<K: Clone + PartialEq + Eq + std::hash::Hash> LruList<K> {
    fn new() -> Self {
        LruList {
            nodes: Vec::new(),
            head: None,
            tail: None,
            free_list: Vec::new(),
        }
    }

    fn push_front(&mut self, key: K) -> usize {
        let idx = if let Some(free_idx) = self.free_list.pop() {
            self.nodes[free_idx] = LruNode {
                key,
                prev: None,
                next: self.head,
            };
            free_idx
        } else {
            let idx = self.nodes.len();
            self.nodes.push(LruNode {
                key,
                prev: None,
                next: self.head,
            });
            idx
        };

        if let Some(old_head) = self.head {
            self.nodes[old_head].prev = Some(idx);
        }
        self.head = Some(idx);
        if self.tail.is_none() {
            self.tail = Some(idx);
        }
        idx
    }

    fn remove(&mut self, idx: usize) {
        let node = &self.nodes[idx];
        let prev = node.prev;
        let next = node.next;

        if let Some(prev_idx) = prev {
            self.nodes[prev_idx].next = next;
        } else {
            self.head = next;
        }

        if let Some(next_idx) = next {
            self.nodes[next_idx].prev = prev;
        } else {
            self.tail = prev;
        }

        self.free_list.push(idx);
    }

    fn move_to_front(&mut self, idx: usize) {
        if self.head == Some(idx) {
            return;
        }
        self.remove(idx);
        let key = self.nodes[idx].key.clone();
        self.push_front(key);
    }

    fn pop_back(&mut self) -> Option<K> {
        let tail_idx = self.tail?;
        let key = self.nodes[tail_idx].key.clone();
        self.remove(tail_idx);
        Some(key)
    }

    fn len(&self) -> usize {
        self.nodes.len() - self.free_list.len()
    }
}

