// Task represents a unit of work to be executed by the worker pool.
// The function receives a context that is canceled when the pool is shutting down
// or when the task's deadline/context is canceled.
type Task func(ctx context.Context) (interface{}, error)

// Result holds the outcome of a task execution.
type Result struct {
	Value interface{}
	Err   error
}

// Pool is a bounded worker pool with context cancellation, backpressure,
// panic recovery, graceful shutdown, and deterministic result delivery.
//
// Public API:
//   - NewPool(numWorkers, queueCapacity int) *Pool
//   - Submit(ctx context.Context, task Task) (<-chan Result, error)
//   - Shutdown(ctx context.Context) error
//   - Wait()
//
// Invariants:
//   - numWorkers must be >= 1; queueCapacity must be >= 0.
//   - Submit returns an error if the pool is closed or if the queue is full (backpressure).
//   - Tasks are executed in FIFO order per worker, but overall completion order is non-deterministic.
//   - Panics in tasks are recovered and converted to errors in the Result.
//   - Shutdown stops accepting new tasks, waits for in-flight tasks to complete (or context cancellation),
//     and releases all resources.
//   - Wait blocks until all workers have exited.
//   - No goroutine leaks: all spawned goroutines are tracked and joined.
//   - No data races: all shared state is protected by mutexes or atomic operations.
type Pool struct {
	numWorkers    int
	queueCapacity int

	// taskQueue is a buffered channel of tasks to be executed.
	// It provides backpressure: Submit blocks if the queue is full.
	taskQueue chan *taskItem

	// workers is the set of active worker goroutines.
	// We track them to ensure graceful shutdown.
	workers []*worker

	// mu protects the state fields below.
	mu sync.Mutex

	// closed indicates whether the pool has been closed (no new submissions allowed).
	closed bool

	// shutdownCtx is the context used to signal workers to stop.
	shutdownCtx    context.Context
	shutdownCancel context.CancelFunc

	// wg tracks all worker goroutines for Wait().
	wg sync.WaitGroup

	// activeTasks tracks the number of tasks currently being executed or queued.
	// Used for graceful shutdown to know when all tasks are done.
	activeTasks int64
}

// taskItem wraps a task with its result channel and context.
type taskItem struct {
	task    Task
	ctx     context.Context
	resultC chan Result
}

// worker represents a single worker goroutine.
type worker struct {
	id   int
	pool *Pool
}

// NewPool creates a new bounded worker pool.
// numWorkers must be >= 1. queueCapacity must be >= 0.
// If queueCapacity is 0, Submit will block until a worker is available (unbounded wait).
// If numWorkers is 0 or negative, it defaults to 1.
// If queueCapacity is negative, it defaults to 0.
func NewPool(numWorkers, queueCapacity int) *Pool {
	if numWorkers < 1 {
		numWorkers = 1
	}
	if queueCapacity < 0 {
		queueCapacity = 0
	}

	p := &Pool{
		numWorkers:    numWorkers,
		queueCapacity: queueCapacity,
		taskQueue:     make(chan *taskItem, queueCapacity),
		workers:       make([]*worker, 0, numWorkers),
	}

	p.shutdownCtx, p.shutdownCancel = context.WithCancel(context.Background())

	// Start workers
	for i := 0; i < numWorkers; i++ {
		w := &worker{id: i, pool: p}
		p.workers = append(p.workers, w)
		p.wg.Add(1)
		go w.run()
	}

	return p
}

// Submit submits a task to the pool. It returns a channel that will receive the Result
// when the task completes, or an error if the submission fails.
//
// Errors:
//   - ErrPoolClosed: if the pool has been closed.
//   - ErrQueueFull: if the queue is full and the context is not canceled.
//   - ctx.Err(): if the provided context is canceled before the task is queued.
//
// The returned channel is buffered with capacity 1, so the caller can read the result
// without blocking the worker.
func (p *Pool) Submit(ctx context.Context, task Task) (<-chan Result, error) {
	if task == nil {
		return nil, errors.New("task cannot be nil")
	}

	p.mu.Lock()
	if p.closed {
		p.mu.Unlock()
		return nil, ErrPoolClosed
	}
	p.mu.Unlock()

	// Check if context is already canceled
	select {
	case <-ctx.Done():
		return nil, ctx.Err()
	default:
	}

	resultC := make(chan Result, 1)
	item := &taskItem{
		task:    task,
		ctx:     ctx,
		resultC: resultC,
	}

	// Try to enqueue the task. If the queue is full, we block until either:
	// - A slot becomes available
	// - The context is canceled
	// - The pool is closed
	select {
	case p.taskQueue <- item:
		atomic.AddInt64(&p.activeTasks, 1)
		return resultC, nil
	case <-ctx.Done():
		return nil, ctx.Err()
	case <-p.shutdownCtx.Done():
		return nil, ErrPoolClosed
	}
}

// Shutdown gracefully shuts down the pool. It stops accepting new tasks,
// waits for in-flight tasks to complete (or until the provided context is canceled),
// and releases all resources.
//
// If the context is canceled before all tasks complete, Shutdown returns ctx.Err().
// After Shutdown returns, no new tasks can be submitted.
func (p *Pool) Shutdown(ctx context.Context) error {
	p.mu.Lock()
	if p.closed {
		p.mu.Unlock()
		return nil // Already closed
	}
	p.closed = true
	p.mu.Unlock()

	// Signal workers to stop by canceling the shutdown context.
	// Workers will finish their current task and then exit.
	p.shutdownCancel()

	// Wait for all workers to exit, respecting the provided context.
	done := make(chan struct{})
	go func() {
		p.wg.Wait()
		close(done)
	}()

	select {
	case <-done:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

