//! Bounded thread-safe LRU cache with TTL.
//!
//! Public API:
//! - `LruCache::new(capacity: usize, ttl: Duration, clock: Arc<dyn Clock>) -> Self`
//! - `get(&self, key: &K) -> Option<V>`
//! - `insert(&self, key: K, value: V)`
//! - `remove(&self, key: &K) -> Option<V>`
//! - `len(&self) -> usize`
//! - `clear(&self)`
//!
//! The cache is bounded by `capacity`. When full, the least recently used entry is evicted.
//! Entries expire after `ttl` from their insertion time. Expired entries are treated as absent
//! on `get` and are lazily removed.
//!
//! Thread safety is provided by `Arc<Mutex<...>>`. All operations acquire the lock.
//! The clock is injectable for deterministic testing.

use std::collections::HashMap;
use std::hash::Hash;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

/// A trait for a clock that can be injected for deterministic testing.
pub trait Clock: Send + Sync {
    /// Returns the current time.
    fn now(&self) -> Instant;
}

/// A real clock using `std::time::Instant`.
pub struct SystemClock;

impl Clock for SystemClock {
    fn now(&self) -> Instant {
        Instant::now()
    }
}

/// A deterministic clock for testing that allows manual advancement.
pub struct TestClock {
    inner: Mutex<Instant>,
}

impl TestClock {
    /// Creates a new test clock starting at the given instant.
    pub fn new(start: Instant) -> Self {
        TestClock {
            inner: Mutex::new(start),
        }
    }

    /// Advances the clock by the given duration.
    pub fn advance(&self, duration: Duration) {
        let mut guard = self.inner.lock().unwrap();
        *guard += duration;
    }
}

impl Clock for TestClock {
    fn now(&self) -> Instant {
        let guard = self.inner.lock().unwrap();
        *guard
    }
}

/// Internal entry stored in the cache.
struct Entry<V> {
    value: V,
    inserted_at: Instant,
