/// Internal LRU list node. We use a doubly-linked list via indices for O(1) operations.
struct LruNode<K, V> {
    key: K,
    value: V,
    inserted_at: Instant,
    prev: Option<usize>,
    next: Option<usize>,
}

/// The LRU cache implementation.
pub struct LruCache<K, V>
where
    K: Eq + Hash + Clone,
    V: Clone,
{
    capacity: usize,
    ttl: Duration,
    clock: Arc<dyn Clock>,
    inner: Mutex<CacheInner<K, V>>,
}

struct CacheInner<K, V>
where
    K: Eq + Hash + Clone,
    V: Clone,
{
    /// Map from key to index in the nodes vector.
    map: HashMap<K, usize>,
    /// Vector of nodes forming the LRU list. Index 0 is the most recently used,
    /// and the last index is the least recently used.
    nodes: Vec<LruNode<K, V>>,
    /// Head of the LRU list (most recently used).
    head: Option<usize>,
    /// Tail of the LRU list (least recently used).
    tail: Option<usize>,
    /// Free list of indices that can be reused.
    free_list: Vec<usize>,
}

impl<K, V> LruCache<K, V>
where
    K: Eq + Hash + Clone,
    V: Clone,
{
    /// Creates a new LRU cache with the given capacity, TTL, and clock.
    ///
    /// # Panics
    /// Panics if `capacity` is 0.
    pub fn new(capacity: usize, ttl: Duration, clock: Arc<dyn Clock>) -> Self {
        if capacity == 0 {
            panic!("Capacity must be greater than 0");
        }
        LruCache {
            capacity,
            ttl,
            clock,
            inner: Mutex::new(CacheInner {
                map: HashMap::new(),
                nodes: Vec::new(),
                head: None,
                tail: None,
                free_list: Vec::new(),
            }),
        }
    }

    /// Gets the value associated with the key, if it exists and has not expired.
    /// If the entry is found, it is marked as most recently used.
    /// If the entry has expired, it is removed and `None` is returned.
    pub fn get(&self, key: &K) -> Option<V> {
        let now = self.clock.now();
        let mut inner = self.inner.lock().unwrap();

        // Check if the key exists
        let idx = match inner.map.get(key) {
            Some(&idx) => idx,
            None => return None,
        };

        // Check if the entry has expired
        let node = &inner.nodes[idx];
        if now.duration_since(node.inserted_at) >= self.ttl {
            // Entry has expired, remove it
            inner.remove_node(idx);
            return None;
        }

        // Move to front (most recently used)
        inner.move_to_front(idx);

        // Return a clone of the value
        Some(inner.nodes[idx].value.clone())
    }

    /// Inserts a key-value pair into the cache.
    /// If the key already exists, its value is updated and it is marked as most recently used.
    /// If the cache is at capacity, the least recently used entry is evicted.
    pub fn insert(&self, key: K, value: V) {
        let now = self.clock.now();
        let mut inner = self.inner.lock().unwrap();

        // Check if the key already exists
        if let Some(&idx) = inner.map.get(&key) {
            // Update the existing entry
            inner.nodes[idx].value = value;
            inner.nodes[idx].inserted_at = now;
            inner.move_to_front(idx);
            return;
        }

        // If at capacity, evict the least recently used entry
        if inner.map.len() >= self.capacity {
            if let Some(tail_idx) = inner.tail {
                let tail_key = inner.nodes[tail_idx].key.clone();
                inner.remove_node(tail_idx);
                inner.map.remove(&tail_key);
            }
        }

        // Insert the new entry at the front
        let idx = inner.add_node(key, value, now);
        inner.map.insert(inner.nodes[idx].key.clone(), idx);
