/// - `len(&self) -> usize`
///
/// # Concurrency
/// All operations are protected by a single `Mutex` inside an `Arc`.
/// The cache is `Clone` via `Arc`, allowing shared ownership across threads.
///
/// # Clock
/// A `Clock` trait allows injecting a deterministic clock for testing.
/// The default implementation uses `std::time::Instant`.

/// Trait for a clock that can be injected for deterministic testing.
pub trait Clock: Send + Sync {
    /// Returns the current time as an `Instant`.
    fn now(&self) -> Instant;
}

/// Default clock implementation using `std::time::Instant`.
pub struct SystemClock;

impl Clock for SystemClock {
    fn now(&self) -> Instant {
        Instant::now()
    }
}

/// A mock clock for deterministic testing.
pub struct MockClock {
    inner: Mutex<Instant>,
}

impl MockClock {
    /// Creates a new mock clock starting at the given instant.
    pub fn new(start: Instant) -> Self {
        MockClock {
            inner: Mutex::new(start),
        }
    }

    /// Advances the clock by the given duration.
    pub fn advance(&self, duration: Duration) {
        let mut guard = self.inner.lock().unwrap();
        *guard += duration;
    }
}

impl Clock for MockClock {
    fn now(&self) -> Instant {
        let guard = self.inner.lock().unwrap();
        *guard
    }
}

/// Internal entry stored in the cache.
struct Entry<V> {
    value: V,
    expires_at: Instant,
}

/// Internal state of the LRU cache.
struct CacheState<K, V> {
    /// Map from key to entry.
    map: HashMap<K, Entry<V>>,
    /// LRU order: front is most recently used, back is least recently used.
    lru_order: Vec<K>,
    /// Maximum number of entries.
    capacity: usize,
    /// TTL for each entry.
    ttl: Duration,
    /// Clock for determining expiry.
    clock: Arc<dyn Clock>,
}

impl<K, V> CacheState<K, V>
where
    K: Clone + Eq + std::hash::Hash,
    V: Clone,
{
    fn new(capacity: usize, ttl: Duration, clock: Arc<dyn Clock>) -> Self {
        CacheState {
            map: HashMap::new(),
            lru_order: Vec::new(),
            capacity,
            ttl,
            clock,
        }
    }

    /// Removes expired entries from the cache.
    fn evict_expired(&mut self) {
        let now = self.clock.now();
        let expired_keys: Vec<K> = self
            .map
            .iter()
            .filter(|(_, entry)| entry.expires_at <= now)
            .map(|(k, _)| k.clone())
            .collect();

        for key in expired_keys {
            self.map.remove(&key);
            if let Some(pos) = self.lru_order.iter().position(|k| k == &key) {
                self.lru_order.remove(pos);
            }
        }
    }

    /// Gets a value from the cache, updating LRU order.
    fn get(&mut self, key: &K) -> Option<V> {
        self.evict_expired();

        if let Some(entry) = self.map.get(key) {
            // Check if expired (should have been caught by evict_expired, but double-check)
            if entry.expires_at <= self.clock.now() {
                self.map.remove(key);
                if let Some(pos) = self.lru_order.iter().position(|k| k == key) {
                    self.lru_order.remove(pos);
                }
                return None;
            }

            // Move to front of LRU order
            if let Some(pos) = self.lru_order.iter().position(|k| k == key) {
                self.lru_order.remove(pos);
            }
            self.lru_order.insert(0, key.clone());

            Some(entry.value.clone())
        } else {
            None
        }
    }

    /// Inserts a value into the cache, evicting LRU if at capacity.
    fn insert(&mut self, key: K, value: V) {
        self.evict_expired();

        let now = self.clock.now();
        let expires_at = now + self.ttl;

        // If key already exists, remove it from LRU order first
        if self.map.contains_key(&key) {
            if let Some(pos) = self.lru_order.iter().position(|k| k == &key) {
                self.lru_order.remove(pos);
            }
        }

        // If at capacity, evict the least recently used entry
        if self.map.len() >= self.capacity && self.capacity > 0 {
            if let Some(lru_key) = self.lru_order.pop() {
                self.map.remove(&lru_key);
            }
        }

        // Insert the new entry
        self.map.insert(
            key.clone(),
            Entry {
                value,
                expires_at,
            },
        );
        self.lru_order.insert(0, key);
    }

    /// Removes a value from the cache.
    fn remove(&mut self, key: &K) -> Option<V> {
        self.evict_expired();

        if let Some(entry) = self.map.remove(key) {
            if let Some(pos) = self.lru_order.iter().position(|k| k == key) {
                self.lru_order.remove(pos);
            }
            Some(entry.value)
        } else {
            None
        }
    }

    /// Returns the number of non-expired entries.
    fn len(&mut self) -> usize {
        self.evict_expired();
        self.map.len()
    }
}

