// Package workerpool provides a bounded worker pool with context cancellation,
// task submission with backpressure, panic recovery, graceful shutdown, and
// deterministic result delivery.
//
// Public API:
//
//   - NewPool(capacity int, workers int) *Pool
//     Creates a new worker pool with the given queue capacity and number of workers.
//     capacity must be >= 0. workers must be >= 1.
//
//   - (*Pool).Submit(ctx context.Context, task func() (interface{}, error)) error
//     Submits a task to the pool. If the pool is full, it blocks until space is available
//     or the context is canceled. Returns an error if the pool is closed or the context
//     is canceled before the task can be enqueued.
//
//   - (*Pool).Shutdown()
//     Initiates graceful shutdown. No new tasks will be accepted. Existing tasks in the
//     queue will be processed. After all queued tasks are done, workers exit.
//
//   - (*Pool).Wait()
//     Blocks until all workers have exited and all submitted tasks have completed.
//     Safe to call multiple times.
//
//   - (*Pool).Close()
//     Alias for Shutdown followed by Wait.
//
// Concurrency invariants:
//   - The pool uses a buffered channel as the task queue. Backpressure is achieved by
//     blocking on send when the queue is full.
//   - Workers pull tasks from the queue and execute them. Panics in tasks are recovered
//     and converted to errors.
//   - Shutdown is signaled via a closed channel. Workers check for shutdown and drain
//     remaining tasks before exiting.
//   - Wait uses a sync.WaitGroup to track active workers.
//   - No goroutine leaks: all workers exit after shutdown and drain.
//   - No data races: all shared state is protected by channels and sync primitives.
package workerpool

import (
	"context"
	"errors"
	"fmt"
	"sync"
)

// Task represents a unit of work to be executed by a worker.
type Task struct {
	fn     func() (interface{}, error)
	result chan<- Result
}

// Result holds the outcome of a task execution.
type Result struct {
	Value interface{}
	Err   error
}

// Pool is a bounded worker pool.
type Pool struct {
	queue    chan Task
	closed   chan struct{}
	closeOnce sync.Once
	wg       sync.WaitGroup
	workers  int
	capacity int
}

// NewPool creates a new worker pool.
// capacity: maximum number of tasks that can be queued (backpressure). Must be >= 0.
// workers: number of worker goroutines. Must be >= 1.
// Panics if capacity < 0 or workers < 1.
func NewPool(capacity int, workers int) *Pool {
	if capacity < 0 {
		panic("workerpool: capacity must be >= 0")
	}
	if workers < 1 {
		panic("workerpool: workers must be >= 1")
	}
	p := &Pool{
		queue:    make(chan Task, capacity),
		closed:   make(chan struct{}),
		workers:  workers,
		capacity: capacity,
	}
	for i := 0; i < workers; i++ {
		p.wg.Add(1)
		go p.worker()
	}
	return p
}

// worker is the main loop for each worker goroutine.
func (p *Pool) worker() {
	defer p.wg.Done()
	for {
		select {
		case <-p.closed:
			// Drain remaining tasks in the queue before exiting.
			for {
				select {
				case task := <-p.queue:
					p.executeTask(task)
				default:
					return
				}
			}
		case task := <-p.queue:
			p.executeTask(task)
		}
	}
}

// executeTask runs the task function, recovering from panics.
func (p *Pool) executeTask(task Task) {
	defer func() {
		if r := recover(); r != nil {
			err := fmt.Errorf("panic in task: %v", r)
			if task.result != nil {
				select {
				case task.result <- Result{Err: err}:
				default:
					// Result channel might be closed or full; ignore.
				}
			}
		}
	}()
	value, err := task.fn()
	if task.result != nil {
		select {
		case task.result <- Result{Value: value, Err: err}:
		default:
			// Result channel might be closed or full; ignore.
		}
	}
}

// Submit submits a task to the pool.
// If the pool is closed, returns ErrPoolClosed.
// If the context is canceled before the task can be enqueued, returns ctx.Err().
// Blocks if the queue is full until space is available or context is canceled.
func (p *Pool) Submit(ctx context.Context, task func() (interface{}, error)) error {
