// Task represents a unit of work to be executed by the worker pool.
// The function receives a context that is canceled when the pool is shutting down
// or when the task's deadline/context is canceled.
type Task func(ctx context.Context) (interface{}, error)

// Result holds the outcome of a task execution.
type Result struct {
	Value interface{}
	Err   error
}

// Pool is a bounded worker pool with context cancellation, backpressure,
// panic recovery, graceful shutdown, and deterministic result delivery.
//
// Public API:
//   - NewPool(numWorkers, queueCapacity int) *Pool
//   - Submit(ctx context.Context, task Task) (<-chan Result, error)
//   - Shutdown(ctx context.Context) error
//   - Close()
//
// Semantics:
//   - numWorkers must be >= 1. If 0 or negative, it defaults to 1.
//   - queueCapacity must be >= 0. If negative, it defaults to 0 (unbounded is not supported; use a large number).
//   - Submit blocks if the queue is full (backpressure) until space is available or ctx is canceled.
//   - If the pool is closed or shutting down, Submit returns an error.
//   - Tasks are executed in FIFO order.
//   - Panics in tasks are recovered and converted to errors in the Result.
//   - Shutdown waits for all submitted tasks to complete or for ctx to be canceled.
//   - Close immediately stops accepting new tasks and cancels running tasks.
//   - Results are delivered via a channel that is closed after the result is sent.
//   - No goroutine leaks: all worker goroutines exit when the pool is closed.
//   - No data races: all shared state is protected by mutexes or atomic operations.
type Pool struct {
	numWorkers    int
	queueCapacity int

	// taskQueue is a buffered channel of tasks to be executed.
	taskQueue chan *taskItem

	// workersDone is closed when all worker goroutines have exited.
	workersDone chan struct{}

	// shutdownOnce ensures Shutdown/Close are idempotent.
	shutdownOnce sync.Once

	// closeOnce ensures Close is idempotent.
	closeOnce sync.Once

	// ctx is the pool's internal context, canceled on Close.
	ctx       context.Context
	cancelCtx context.CancelFunc

	// wg tracks active worker goroutines.
	wg sync.WaitGroup

	// closed indicates whether the pool has been closed.
	closed atomic.Bool

	// shuttingDown indicates whether Shutdown has been called.
	shuttingDown atomic.Bool

	// activeTasks tracks the number of tasks currently being executed.
	activeTasks atomic.Int64

	// pendingTasks tracks the number of tasks in the queue or being executed.
	pendingTasks atomic.Int64
}

// taskItem wraps a task with its result channel and context.
type taskItem struct {
	task    Task
	ctx     context.Context
	resultC chan Result
}

// NewPool creates a new worker pool with the specified number of workers and queue capacity.
// If numWorkers is <= 0, it defaults to 1.
// If queueCapacity is < 0, it defaults to 0.
func NewPool(numWorkers, queueCapacity int) *Pool {
	if numWorkers <= 0 {
		numWorkers = 1
	}
	if queueCapacity < 0 {
		queueCapacity = 0
	}

	ctx, cancel := context.WithCancel(context.Background())

	p := &Pool{
		numWorkers:    numWorkers,
		queueCapacity: queueCapacity,
		taskQueue:     make(chan *taskItem, queueCapacity),
		workersDone:   make(chan struct{}),
		ctx:           ctx,
		cancelCtx:     cancel,
	}

	// Start worker goroutines.
	for i := 0; i < numWorkers; i++ {
		p.wg.Add(1)
		go p.worker()
	}

	// Start a goroutine that closes workersDone when all workers exit.
	go func() {
		p.wg.Wait()
		close(p.workersDone)
	}()

	return p
}

// worker is the main loop for each worker goroutine.
func (p *Pool) worker() {
	defer p.wg.Done()

	for {
		select {
		case <-p.ctx.Done():
			// Pool is closing; drain remaining tasks and exit.
			p.drainQueue()
			return
		case item, ok := <-p.taskQueue:
			if !ok {
				// Queue is closed; exit.
				return
			}
			p.executeTask(item)
		}
	}
