func (p *Pool) drainQueue() {
	for {
		select {
		case item, ok := <-p.taskQueue:
			if !ok {
				return
			}
			p.executeTask(item)
		default:
			return
		}
	}
}

// executeTask runs a single task with panic recovery and delivers the result.
func (p *Pool) executeTask(item *taskItem) {
	p.activeTasks.Add(1)
