// The Execute function is called with a context that is canceled when the pool
// is shutting down or when the task is explicitly canceled.
type Task struct {
	// ID is a unique identifier for the task, useful for debugging and result tracking.
	ID string
	// Execute is the function to run. It receives a context that may be canceled.
	// It returns a result and an error. If it panics, the panic is recovered and
	// converted to an error.
	Execute func(ctx context.Context) (interface{}, error)
}

// Result represents the outcome of a task execution.
type Result struct {
	// TaskID is the ID of the task that produced this result.
	TaskID string
	// Value is the value returned by the task's Execute function.
	Value interface{}
	// Err is the error returned by the task's Execute function, or a recovered panic.
	Err error
}

// Pool is a bounded worker pool that executes tasks with concurrency limits,
// supports context cancellation, graceful shutdown, panic recovery, and
// deterministic result delivery.
//
// Public API:
//   - NewPool(capacity int) *Pool: Creates a new pool with the given worker capacity.
//     Capacity must be positive.
//   - Submit(ctx context.Context, task Task) error: Submits a task to the pool.
//     Returns an error if the pool is closed, the context is canceled, or the
//     task queue is full (backpressure).
//   - Results() <-chan Result: Returns a channel that receives results from completed tasks.
//     The channel is closed when the pool is fully shut down and all tasks have completed.
//   - Shutdown(ctx context.Context) error: Initiates graceful shutdown. No new tasks
//     are accepted. Existing tasks are allowed to complete or are canceled based on
//     the provided context. Returns an error if the context is canceled before all
//     tasks complete.
//   - Close(): Immediately closes the pool, canceling all pending and running tasks.
//     The Results channel will be closed after all workers exit.
//
// Concurrency Invariants:
//   - At most `capacity` tasks are executing concurrently.
//   - The Results channel is closed exactly once, after all workers have exited.
//   - No goroutine leaks: all worker goroutines exit when the pool is closed.
//   - No data races: all shared state is protected by mutexes or atomic operations.
type Pool struct {
	capacity int

	// taskQueue is a buffered channel that holds pending tasks.
	// Its capacity is equal to the pool's capacity, providing backpressure.
	taskQueue chan Task

	// results is the channel where completed task results are sent.
	results chan Result

	// workersDone is a WaitGroup to track active worker goroutines.
	workersDone sync.WaitGroup

	// closeOnce ensures Close() is idempotent.
	closeOnce sync.Once

	// shutdownOnce ensures Shutdown() is idempotent.
	shutdownOnce sync.Once

	// closed indicates whether the pool has been closed.
	closed atomic.Bool

	// shutdownStarted indicates whether shutdown has been initiated.
	shutdownStarted atomic.Bool

	// activeTasks tracks the number of tasks currently being executed.
	// Used to ensure we wait for all tasks to complete during shutdown.
	activeTasks atomic.Int64

	// taskDone is a channel used to signal that a task has completed.
	// This helps in coordinating shutdown.
	taskDone chan struct{}

	// mu protects access to closed and shutdownStarted states for consistency.
	mu sync.Mutex
}

// NewPool creates a new worker pool with the specified capacity.
// Capacity must be a positive integer. If capacity is zero or negative,
// it defaults to 1.
func NewPool(capacity int) *Pool {
	if capacity <= 0 {
		capacity = 1
	}

	p := &Pool{
		capacity:  capacity,
		taskQueue: make(chan Task, capacity),
		results:   make(chan Result, capacity),
		taskDone:  make(chan struct{}, capacity),
	}

	// Start worker goroutines.
	for i := 0; i < capacity; i++ {
		p.workersDone.Add(1)
		go p.worker()
	}

	return p
}

// worker is the main loop for each worker goroutine.
// It reads tasks from the taskQueue, executes them, and sends results to the results channel.
func (p *Pool) worker() {
	defer p.workersDone.Done()

	for {
		// Check if the pool is closed before attempting to receive a task.
		if p.closed.Load() {
			return
		}

		select {
		case task, ok := <-p.taskQueue:
			if !ok {
				// taskQueue is closed, exit worker.
				return
			}

			// Increment active task count.
			p.activeTasks.Add(1)

			// Execute the task with panic recovery.
			result := p.executeTask(task)

			// Decrement active task count.
			p.activeTasks.Add(-1)

			// Send result to the results channel.
			// Use a select with a default case to avoid blocking if the results channel
			// is full and the pool is shutting down. However, for deterministic delivery,
			// we should block until the result is sent, unless the pool is closed.
			// To avoid deadlock during shutdown, we check if the pool is closed.
			select {
			case p.results <- result:
			case <-p.taskDone:
				// If taskDone is signaled, it means we're shutting down and should
				// not block on sending results. Drop the result.
				// This is a tradeoff: during forced shutdown, some results may be lost.
			}

			// Signal that a task has completed.
			select {
			case p.taskDone <- struct{}{}:
			default:
				// taskDone channel is full, which is fine.
			}

		case <-p.taskDone:
			// This case is triggered when a task completes, but we don't need to do
			// anything here. It's mainly for coordination during shutdown.
			// We continue to loop and check for new tasks or closure.
			continue
		}
	}
}

// executeTask runs the task's Execute function with panic recovery.
func (p *Pool) executeTask(task Task) Result {
	result := Result{
		TaskID: task.ID,
